INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass staatliche Förderung immer die IT-Branche ankurbelt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Wirkung hängt von Umsetzung ab"}, {"text": "Ja", "correct": false, "because": "Nicht automatisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich staatliche Maßnahmen für eine IT-Firma nutze?', 3, '[{"text": "Fördermittelanträge", "correct": true, "because": "Sichert finanzielle Unterstützung"}, {"text": "Schnelle Expansion", "correct": false, "because": "Planung wichtiger"}, {"text": "Neues Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen beeinflussen die IT-Branche positiv?', 5, '[{"text": "Steuersenkungen", "correct": true, "because": "Erhöht Investitionen"}, {"text": "Subventionen", "correct": true, "because": "Fördert Innovation"}, {"text": "Höhere Zinsen", "correct": false, "because": "Bremst Kredite"}, {"text": "Weniger Personal", "correct": false, "because": "Kein Konjunkturziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Konjunkturpolitik kann Arbeitsplätze schaffen. b) Sie wirkt immer sofort.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wirkung oft verzögert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Förderprogramme für IT-Projekte prüfe?', 4, '[{"text": "Förderkriterien", "correct": false, "because": "Bestimmen Zugang"}, {"text": "Zeitrahmen", "correct": false, "because": "Wichtig für Planung"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein Konjunkturfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Steuersenkungen immer die IT-Nachfrage steigern?', 2, '[{"text": "Nein", "correct": true, "because": "Hängt von Marktlage ab"}, {"text": "Ja", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit staatlicher Förderung in der IT?', 3, '[{"text": "Innovationsförderung", "correct": true, "because": "Stärkt Wettbewerb"}, {"text": "Schnellere Lieferung", "correct": false, "because": "Kein direktes Ziel"}, {"text": "Weniger Personal", "correct": false, "because": "Nicht konjunkturrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen Konjunkturmaßnahmen in der IT effektiv?', 5, '[{"text": "Zielgenaue Subventionen", "correct": true, "because": "Fördert Schlüsselbereiche"}, {"text": "Investitionsanreize", "correct": true, "because": "Regt Ausgaben an"}, {"text": "Höhere Steuern", "correct": false, "because": "Bremst Wachstum"}, {"text": "Weniger Dokumentation", "correct": false, "because": "Kein direkter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Konjunkturpolitik fördert IT-Startups. b) Sie hilft nur Großfirmen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Breite Wirkung möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Konjunkturmaßnahmen für eine IT-Firma zu nutzen?', 4, '[{"text": "Wirtschaftsanalyse", "correct": false, "because": "Zeigt Bedarf"}, {"text": "Förderanträge", "correct": false, "because": "Sichern Mittel"}, {"text": "Firmenlogo", "correct": true, "because": "Kein Konjunkturfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Steigern staatliche Investitionen immer die IT-Produktion?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Nachfrage"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt Konjunkturpolitik für IT-Firmen?', 4, '[{"text": "Mehr Investitionen", "correct": true, "because": "Fördert Wachstum"}, {"text": "Arbeitsplatzschaffung", "correct": true, "because": "Erhöht Beschäftigung"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein direkter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Konjunkturmaßnahmen immer die IT-Preise senken. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Preise marktabhängig"}, {"text": "Ja", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um staatliche Förderung für ein IT-Projekt zu nutzen?', 3, '[{"text": "Förderprogramme", "correct": true, "because": "Bieten finanzielle Hilfe"}, {"text": "Höhere Steuern", "correct": false, "because": "Bremst Mittel"}, {"text": "Neue Designs", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Konjunkturpolitik kann IT-Innovation fördern. b) Sie wirkt nur kurzfristig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Langfristige Effekte möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei staatlicher IT-Förderung?', 5, '[{"text": "Antragsfristen", "correct": true, "because": "Sichern Zugang"}, {"text": "Förderbedingungen", "correct": true, "because": "Definieren Nutzung"}, {"text": "Büroausstattung", "correct": false, "because": "Kein Einfluss"}, {"text": "Marketingpläne", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich Konjunkturmaßnahmen für IT nutze?', 3, '[{"text": "Wirtschaftslage", "correct": false, "because": "Zeigt Bedarf"}, {"text": "Förderkriterien", "correct": false, "because": "Bestimmen Zugang"}, {"text": "Firmenfarben", "correct": true, "because": "Kein Konjunkturfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Fördert Konjunkturpolitik immer die IT-Nachfrage?', 3, '[{"text": "Nein", "correct": true, "because": "Abhängig von Umsetzung"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob staatliche Eingriffe immer IT-Jobs schaffen?', 2, '[{"text": "Nein", "correct": true, "because": "Erfolg variiert"}, {"text": "Ja", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend, wenn ich Konjunkturmaßnahmen für IT plane?', 4, '[{"text": "Förderstrategie", "correct": true, "because": "Lenkt Mittel gezielt"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Planung zählt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]');
